sec.code:
n_inc_studies <- n_distinct(es_inc$study_id); n_inc_es <- nrow(es_inc)
cf <- function(name, par) { m <- summary(readRDS(file.path("_brms_cache/primary", paste0(name, ".rds"))))$fixed[par, ]
  sprintf("%.2f (95%% CrI, %.2f to %.2f)", m$Estimate, m[["l-95% CI"]], m[["u-95% CI"]]) }

if (!is.null(fits$fit_gram_pos) && !is.null(fits$fit_gram_neg)) { gpos_post <- pooled_summary(fits$fit_gram_pos) gneg_post <- pooled_summary(fits$fit_gram_neg)
density_df <- bind_rows( tibble(OR = base_post$OR_draws, group = "Overall"), tibble(OR = gneg_post$OR_draws, group = "Gram-negative"), tibble(OR = gpos_post$OR_draws, group = "Gram-positive") ) |> mutate(group = factor(group, levels = c("Gram-positive", "Overall", "Gram-negative")))
ggplot(density_df, aes(x = OR, y = group, fill = group)) + stat_halfeye(alpha = 0.75, point_color = "black", point_size = 3, interval_color = "black", interval_size = 2, .width = 0.95, normalize = "xy") + geom_vline(xintercept = 1, linetype = "dashed", color = "gray40", linewidth = 0.8) + scale_fill_manual( values = c("Gram-positive" = "#2196C4", "Overall" = "#607D8B", "Gram-negative" = "#C75450"), guide = "none") + scale_x_continuous(limits = c(0.5, 6), breaks = 1:6, name = "Pooled odds ratio (short vs long time-to-positivity)") + labs(y = NULL, subtitle = "Mixed follow-up (predominantly 30-day mortality); short vs long time-to-positivity.\nPoint, posterior median; bar, 95% credible interval. Dashed line, OR = 1 (no effect).") + theme_minimal(base_size = 12) + theme(panel.grid.major.y = element_blank(), panel.grid.minor = element_blank(), axis.text.y = element_text(size = 12)) }

if (nrow(es_pb) >= 3) { fit_pb <- brm( bf(yi | se(sei) ~ 1 + (1 | study_id)), data = es_pb, prior = c(prior(normal(0, 1), class = "Intercept"), prior(cauchy(0, 0.5), class = "sd")), chains = 4, iter = 4000, warmup = 1000, cores = 4, backend = "cmdstanr", control = list(adapt_delta = 0.99), file = "_brms_cache/primary/fit_pb", file_refit = "on_change", silent = 2, refresh = 0 ) pb_post <- pooled_summary(fit_pb)
forest_pb <- es_pb |> mutate(or = exp(yi), ci_low = exp(yi - 1.96*sei), ci_high = exp(yi + 1.96*sei), lbl = paste0(study_id, ifelse(arm_id == "all", "", paste0(" [", arm_id, "]"))), type = "Study") |> bind_rows(tibble(lbl = "POOLED", or = pb_post$median_OR, ci_low = pb_post$ci_OR[1], ci_high = pb_post$ci_OR[2], type = "Pooled"))
ggplot(forest_pb, aes(x = or, y = reorder(lbl, or), color = type)) + geom_vline(xintercept = 1, linetype = "dashed", color = "gray50") + geom_point(size = 2.5) + geom_errorbar(aes(xmin = pmax(ci_low, 0.05), xmax = pmin(ci_high, 50)), width = 0.25, orientation = "y") + scale_color_manual(values = c("Study" = "#2c7fb8", "Pooled" = "darkred")) + scale_x_log10(breaks = c(0.1, 0.5, 1, 2, 5, 10, 25), limits = c(0.05, 50)) + labs(x = "OR (short vs long TTP)", y = NULL, color = NULL, title = sprintf("Persistent bacteremia / IE — pooled OR %.2f [%.2f, %.2f]", pb_post$median_OR, pb_post$ci_OR[1], pb_post$ci_OR[2])) + theme_minimal(base_size = 10) + theme(legend.position = "bottom") } else { cat("Fewer than 3 effect sizes available — cannot fit pooled model.") }
